def transition(self, case_id, expected, action, actor, now):
    if type(now) is not int or type(expected) is not int:
        raise ValueError("integer_clock_and_revision_required")
    with sqlite3.connect(self.path, isolation_level=None) as db:
        db.execute("BEGIN IMMEDIATE")
        row = db.execute("SELECT * FROM cases WHERE id=?", (case_id,)).fetchone()
        if row is None:
            raise KeyError(case_id)
        _, state, revision, expires, owner, verifier, epoch = row
        if expected != revision:
            raise ValueError("stale_revision")
        if now >= expires:
            raise ValueError("expired")
        if action == "verify" and state == "review" and actor != owner:
            state, verifier = "verified", actor
        elif (action == "restore" and state == "verified"
              and actor not in (owner, verifier)):
            state, epoch = "restored", epoch + 1
        else:
            raise ValueError("invalid_transition_or_actor")
        db.execute("UPDATE cases SET state=?, revision=?, verifier=?, epoch=? "
                   "WHERE id=?", (state, revision + 1, verifier, epoch, case_id))
        db.commit()
    return self.read(case_id)

def deliver(self, event_id):
    if event_id in self.sent:
        return self.sent[event_id]
    event = json.loads(self.events[event_id])
    pref = self.preferences.get(event["user"],
                                dict(show_values=False, enabled=True, version=0))
    if not pref["enabled"]:
        return {"status": "suppressed"}
    # A política é aplicada agora, não no instante de enfileirar.
    message = {"title": "Atualização financeira",
               "body": "Consulte os detalhes no aplicativo.",
               "preference_version": pref["version"]}
    if pref["show_values"]:
        whole, cents = divmod(event["amount_cents"], 100)
        message["body"] = f"Crédito disponível: R$ {whole},{cents:02d}."
    # Aceitação local pelo provedor simulado, sem garantia de leitura.
    self.sent[event_id] = {"status": "accepted", "message": message}
    return self.sent[event_id]

def configure(self, user, show_values=False, enabled=True):
    if type(show_values) is not bool or type(enabled) is not bool:
        raise ValueError("boolean_preferences_required")
    old = self.preferences.get(user, {"version": 0})
    self.preferences[user] = dict(show_values=show_values, enabled=enabled,
                                  version=old["version"] + 1)

def enqueue(self, event):
    if set(event) != {"id", "user", "version", "kind", "amount_cents"}:
        raise ValueError("schema")
    if (type(event["version"]) is not int or event["version"] != 1
            or event["kind"] not in ("cashback", "income")):
        raise ValueError("unsupported")
    cents = event["amount_cents"]
    if type(cents) is not int or cents < 0:
        raise ValueError("money")
    payload = json.dumps(event, sort_keys=True)
    old = self.events.get(event["id"])
    if old is not None and old != payload:
        raise ValueError("id_conflict")
    self.events[event["id"]] = payload

# max_age mede a idade em segundos simulados.
# Uma lacuna não recebe um valor zero substituto.
# A interface deve preservar complete e gaps.
def summarize(self, now, max_age=60):
    total, gaps = 0, {}
    if not self.active:
        return dict(cents=None, complete=False, gaps={"consent": "revoked"})
    for key in sorted(self.required):
        item = self.resources.get(key)
        if item is None:
            gaps[key] = "missing"
        elif item.status != "complete":
            gaps[key] = item.status
        elif not 0 <= now - item.observed_at <= max_age:
            gaps[key] = "stale_or_future"
        else:
            total += item.cents
    return dict(cents=total, complete=not gaps, gaps=gaps)

# A geração acompanha o recurso desde a solicitação.
def apply(self, key, resource):
    if not self.active or resource.consent_epoch != self.consent_epoch:
        return False
    if type(resource.sequence) is not int or resource.sequence < 0:
        raise ValueError("integer_sequence_required")
    if key not in self.required:
        raise ValueError("unknown_resource")
    if resource.status not in ("complete", "unsupported", "unavailable"):
        raise ValueError("status")
    if resource.status == "complete":
        if type(resource.cents) is not int or resource.cents < 0:
            raise ValueError("amount")
    elif resource.cents is not None:
        raise ValueError("unknown_is_not_zero")
    old = self.resources.get(key)
    if old and resource.sequence <= old.sequence:
        return False
    self.resources[key] = resource
    return True

# day é uma data civil já validada.
# zone usa regras IANA, não um offset fixo.
# A ida e volta detecta horários inexistentes.
# fold considera as duas ocorrências de uma dobra.
def local_instant(day, hour, minute, zone):
    # Política proposta: primeiro instante válido; na dobra, primeiro UTC.
    naive = datetime.combine(day, time(hour, minute))
    for shift in range(181):
        candidate = naive + timedelta(minutes=shift)
        valid = []
        for fold in (0, 1):
            instant = candidate.replace(tzinfo=zone, fold=fold).astimezone(UTC)
            roundtrip = instant.astimezone(zone).replace(tzinfo=None)
            if roundtrip == candidate:
                valid.append(instant)
        if valid:
            return min(valid)
    raise ValueError("no_valid_instant")

class CivilDate implements Comparable<CivilDate> {
  final int year, month, day;
  const CivilDate(this.year, this.month, this.day);
  int get orderKey => year * 10000 + month * 100 + day;
  @override
  int compareTo(CivilDate other) =>
      orderKey.compareTo(other.orderKey);
}

