assert gate(baseline, candidate) == "PAUSE_SUCCESS"
assert gate(baseline, baseline) == "ELIGIBLE_FOR_REVIEW"
assert gate(baseline, baseline, False) == "HOLD_TELEMETRY"
small = {"n": 10, "rate": 1.0, "p95": 100}
assert gate(baseline, small) == "HOLD_SAMPLE"

enum JourneyOutcome { completed, failed, unknown }

class JourneySignal {
  final String attemptId;
  final String release;
  final JourneyOutcome outcome;
  final int elapsedMs;
  const JourneySignal(this.attemptId, this.release,
      this.outcome, this.elapsedMs);
}

abstract class BoundedTelemetry {
  bool offer(JourneySignal signal);
}

Future<T> observed<T>(
  Future<T> Function() task,
  BoundedTelemetry telemetry,
  String attemptId,
  String release,
) async {
  final watch = Stopwatch()..start();
  try {
    final result = await task();
    telemetry.offer(JourneySignal(attemptId, release,
        JourneyOutcome.completed, watch.elapsedMilliseconds));
    return result;
  } catch (_) {
    telemetry.offer(JourneySignal(attemptId, release,
        JourneyOutcome.unknown, watch.elapsedMilliseconds));
    rethrow;
  }
}

def route(scores, available, urgent=False, threshold=0.75, min_weight=4):
    if type(urgent) is not bool:
        raise ValueError("urgent must be boolean")
    if urgent:
        return {"queue": "human_urgent", "reason": "declared_urgency"}
    validate_ranking(scores, threshold, min_weight)
    total = sum(scores.values())
    if total < min_weight:
        return {"queue": "human_general", "reason": "insufficient"}
    ranked = sorted(scores.items(), key=lambda x: (-x[1], x[0]))
    intent, weight = ranked[0]
    confidence = weight / total
    if confidence < threshold or intent not in available:
        return {"queue": "human_general", "reason": "abstention"}
    return {"queue": intent, "reason": "ranked", "share": confidence}

